package com.example.hungdm.service

import com.example.hungdm.domain.model.Song
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow

object PlayerState {
 private val _playlist = MutableStateFlow<List<Song>>(emptyList())
 val playlist: StateFlow<List<Song>> = _playlist

 private val _currentIndex = MutableStateFlow<Int?>(null)
 val currentIndex: StateFlow<Int?> = _currentIndex

 private val _isPlaying = MutableStateFlow(false)
 val isPlaying: StateFlow<Boolean> = _isPlaying

 private val _position = MutableStateFlow(0L)
 val position: StateFlow<Long> = _position

 private val _duration = MutableStateFlow(0L)
 val duration: StateFlow<Long> = _duration

 fun setPlaylist(list: List<Song>, startIndex: Int = 0) {
 _playlist.value = list
 _currentIndex.value = if (list.isEmpty()) null else startIndex.coerceIn(list.indices)
 }

 fun setCurrentIndex(index: Int?) { _currentIndex.value = index }
 fun setPlaying(playing: Boolean) { _isPlaying.value = playing }
 fun setPosition(pos: Long) { _position.value = pos }
 fun setDuration(d: Long) { _duration.value = d }
}
